type Panel='world'|'people'|'activity'|'dialogues'|'invitations'|'agreements'|'usage'|'about';
type Invitation={id:number;host_id:string;host_name:string;site_id:string;target_day:number;target_hour:number;target_minute:number;people:Array<{npc_id:string;name:string;response:'pending'|'accepted'|'declined';travel_decision:'going'|'skipping'|null;attended_at:string|null}>};
type Agreement={id:number|string;proposer_id:string;recipient_id:string;proposer_name:string;recipient_name:string;source_message_id:number|string;terms:string;status:'proposed'|'signed'|'declined';proposed_day:number;decided_day:number|null;created_at:string;decided_at:string|null};
type ApiState={world:{startedAt:string;day:number;hour:number;minute:number;phase:number;elapsedSeconds:number};npcs:Array<{id:string;x:number;z:number;emotion:string;mode:string;stamina:number;hunger:number;thirst:number;coins:number;next_thought_at:string|null;planned_wake_at:string|null}>;budget:{enabled:boolean;budgetUsd:number;spentUsd:number;reservedUsd:number;remainingUsd:number;paused:boolean;models:{decision:string;conversation:string;summary:string}}};
type Dialogue={id:number|string;reply_to_message_id:number|string|null;reply_to_speaker_name:string|null;reply_to_content:string|null;world_day:number;world_hour:number;world_minute:number;from_npc_id:string|null;to_npc_id:string|null;participants:string[];speaker_name:string;content:string;created_at:string};
type NpcActivity={affect:{mood:string;pressure:number;valence:number};bonds:Array<{name:string;other_id:string;warmth:number;trust:number;tension:number}>;feelings:Array<{id:number;world_day:number;emotion:string;intensity:number;cause:string;other_id:string|null;other_name:string|null}>;bondEmotions:Array<{other_id:string;emotion:string;strength:number;occurrences:number}>;npc:{id:string;name:string;mode:string;emotion:string;stamina:number;hunger:number;thirst:number;coins:number;last_decision_at:string|null};coins:Array<{id:number;other_id:string|null;kind:'earned'|'given'|'received'|'spent';amount:number;world_day:number;balance_after:number;created_at:string}>;inventory:Array<{item_id:string;quantity:number}>;itemEvents:Array<{id:number;other_id:string|null;item_id:string;kind:string;world_day:number;need_before:number|null;need_after:number|null;joy_gain:number;created_at:string}>;memory:{summary:string;last_summarized_day:number;updated_at:string}|null;memoryEvents:Array<{id:number;kind:string;summary:string;importance:number;world_day:number}>;explorations:Array<{site_id:string;discovery:string;world_day:number}>;beliefs:Array<{topic:string;stance:number;reason:string}>;notifications:Array<{id:number;message:string;created_at:string}>;invitations:Invitation[];agreements:Agreement[];decisions:Array<{id:number;world_day:number;action:string;arguments:Record<string,unknown>;outcome:string;thought:string;created_at:string}>;dialogue:Array<{id:number;world_day:number;world_hour:number;world_minute:number;speaker_name:string;content:string;created_at:string}>};
type UsageReport={reportStartedAt:string;filters:{prompt_tokens:number;completion_tokens:number;total_tokens:number;cost_usd:number;requests:number};daily:Array<{date:string;tokens:number;cost_usd:number;respan_cost_usd:number;jev_cost_usd:number;jev_113_cost_usd:number;nano_cost_usd:number;ling_cost_usd:number;mistral_cost_usd:number;qwen_cost_usd:number;other_cost_usd:number;requests:number}>;characters:Array<{character:string;npc_id:string|null;tokens:number;cost_usd:number;requests:number}>;models:Array<{model:string;purpose:string;tokens:number;cost_usd:number;requests:number}>;budget:{budgetUsd:number;spentUsd:number;reservedUsd:number;remainingUsd:number;paused:boolean;enabled:boolean}};
type LiveEvent={eventId?:number;npcId:string;npcName:string;stage:string;status:string;tool?:string;thought?:string;outcome?:string;at:string};
type ActionToast={id:string;npcName:string;action:string;description:string;outcome:string};
type Decision=NpcActivity['decisions'][number];

const emotionLabel=(value:string)=>emotionById.get(value)?.label??({unanswered:'Ignorado',happy:'Alegria',sad:'Tristeza',angry:'Raiva',worried:'Preocupação'} as Record<string,string>)[value]??value;
const itemIcons:Record<string,string>={apple:'🍎',bread:'🍞',water:'💧',juice:'🧃',pear:'🍐',plum:'🍑',grapes:'🍇',banana:'🍌',orange:'🍊',peach:'🍑',fig:'🫐',berries:'🫐',carrot:'🥕',tomato:'🍅',corn:'🌽',potato:'🥔',pumpkin:'🎃',soup:'🥣',salad:'🥗',cheese:'🧀',egg:'🥚',porridge:'🥣',rice:'🍚',beans:'🫘',cracker:'🥨',honeycake:'🍰',nuts:'🥜',herbaltea:'🍵',minttea:'🍵',chamomile:'🍵',lemontea:'🍵',berrytea:'🍵',lemonade:'🍋',limewater:'🍋',orangeade:'🍊',grapejuice:'🍇',pearjuice:'🍐',applejuice:'🍎',plumjuice:'🍑',berryjuice:'🫐',coconutwater:'🥥',springwater:'💧',warmmilk:'🥛',coldmilk:'🥛',honeywater:'🍯',gingertea:'🍵',cinnamontea:'🍵',melonwater:'🍈',flowertea:'🌼',spiceddrink:'🍵'};
const actionLabel=(value:string)=>({buy_item:'comprou na banca',consume_item:'consumiu um item',donate_item:'doou um item',leave_world:'partiu para o exterior',say_to_person:'conversou',say_to_group:'falou com o grupo',visit_landmark:'visitou um lugar',walk_to_person:'foi encontrar alguém',observe_animal:'observou um animal',invite_to_see_animal:'convidou alguém para ver um animal'} as Record<string,string>)[value]??value.replaceAll('_',' ');

const stamp=(item:{world_day:number;world_hour:number;world_minute:number})=>`${formatWorldDate(item.world_day)} · ${String(item.world_hour).padStart(2,'0')}:${String(item.world_minute).padStart(2,'0')}`;
const money=(amount:number)=>`$${Number(amount??0).toFixed(4)}`;
const purposeName=(value:string)=>value==='decision'?'Decisão':value==='dialogue'?'Diálogo':'Resumo diário';
const formatWait=(value:string)=>{const total=Math.max(0,Math.ceil((new Date(value).getTime()-Date.now())/1000));const hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60),seconds=total%60;return hours?`${hours} h ${minutes} min`:minutes?`${minutes} min ${seconds} s`:`${seconds} s`;};

function RecentActions({decisions,emptyMessage}:{decisions:Decision[]|undefined;emptyMessage:string}) {
  return <div className="journal-list recent-actions">{decisions?.length?decisions.slice().reverse().map(item=><article key={item.id}><small>{formatWorldDate(item.world_day)} · ferramenta <code>{item.action}</code></small><p>{item.outcome}</p><span>Dados enviados</span><pre>{JSON.stringify(item.arguments??{},null,2)}</pre></article>):<p className="resident-empty">{emptyMessage}</p>}</div>;
}

function InvitationList({items}:{items:Invitation[]}) {
  return <div className="invitation-list">{items.length?items.map(item=><article key={item.id}><header><b>{item.host_name} convidou para {landmarks.find(place=>place.id===item.site_id)?.name??item.site_id}</b><time>{formatWorldDate(item.target_day)} · {String(item.target_hour).padStart(2,'0')}:{String(item.target_minute).padStart(2,'0')}</time></header><div>{item.people.map(person=><span key={person.npc_id}><strong>{person.name}</strong> · {person.attended_at?'compareceu':person.response==='declined'?'recusou':person.response==='pending'?'aguarda resposta':person.travel_decision==='going'?'decidiu ir':person.travel_decision==='skipping'?'decidiu não ir':'aceitou'}</span>)}</div></article>):<p className="resident-empty">Ainda não há convites. Eles aparecerão quando os moradores combinarem um encontro durante uma conversa.</p>}</div>;
}

export default function App() {
  const mount=useRef<HTMLDivElement>(null),world=useRef<World|null>(null),audio=useRef(new AmbientAudio());
  const [time,setTime]=useState(()=>getWorldTime()),[apiState,setApiState]=useState<ApiState|null>(null),[muted,setMuted]=useState(true),[zoom,setZoom]=useState(76);
  const [panel,setPanel]=useState<Panel>('world'),[selectedId,setSelectedId]=useState('ka'),[menuOpen,setMenuOpen]=useState(false),[moreOpen,setMoreOpen]=useState(false);
  const [residentView,setResidentView]=useState<'overview'|'inventory'|'relationships'|'emotions'|'journal'|'records'>('overview');
  const [emotionDetail,setEmotionDetail]=useState<string|null>(null);
  const [emotionTargetId,setEmotionTargetId]=useState<string|null>(null);
  const [emotionSearch,setEmotionSearch]=useState('');
  const [dialogues,setDialogues]=useState<Dialogue[]>([]),[agreements,setAgreements]=useState<Agreement[]>([]),[invitations,setInvitations]=useState<Invitation[]>([]),[npcActivity,setNpcActivity]=useState<NpcActivity|null>(null),[chatResidentId,setChatResidentId]=useState<string|null>(null),[chatPartnerId,setChatPartnerId]=useState<string|null>(null);
  const chatEndRef=useRef<HTMLDivElement>(null);
  const [liveEvents,setLiveEvents]=useState<LiveEvent[]>([]);
  const [actionToasts,setActionToasts]=useState<ActionToast[]>([]);
  const toastTimers=useRef(new Set<number>());
  const seenActionEvents=useRef(new Set<string>());
  const selectedIdRef=useRef(selectedId);selectedIdRef.current=selectedId;
  const worldStartRef=useRef<string|null>(null);
  const [period,setPeriod]=useState('month'),[filterNpc,setFilterNpc]=useState('all'),[filterModel,setFilterModel]=useState('all'),[filterPurpose,setFilterPurpose]=useState('all'),[usage,setUsage]=useState<UsageReport|null>(null),[fullscreen,setFullscreen]=useState(false);
  const selected=profiles.find(person=>person.id===selectedId)??profiles[0];
  useEffect(()=>{
    if(!mount.current)return;
    let stopped=false,instance:World|null=null;
    if(mount.current){instance=new World(mount.current,value=>setZoom(Math.round(value*100)),id=>{setSelectedId(id);setResidentView('overview');setEmotionDetail(null);setEmotionTargetId(null);setPanel('people');});world.current=instance;}
    let retry:number|undefined;
    let socket:WebSocket|null=null;
    const connect=()=>{
      if(stopped)return;
      socket=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws`);
      socket.onmessage=event=>{
        if(stopped)return;
        try {
          const packet=JSON.parse(event.data) as {type:string;payload:any};
          if(packet.type==='state'){
            const state=packet.payload as ApiState;
            if(worldStartRef.current&&worldStartRef.current!==state.world.startedAt){setDialogues([]);setAgreements([]);setInvitations([]);window.dispatchEvent(new Event('theote:agreements-changed'));window.dispatchEvent(new Event('theote:invitations-changed'));setLiveEvents([]);setActionToasts([]);seenActionEvents.current.clear();setNpcActivity(null);}
            worldStartRef.current=state.world.startedAt;
            setApiState(state);setTime(state.world);instance?.setDayPhase(state.world.phase);instance?.setWorldElapsedSeconds(state.world.elapsedSeconds);instance?.applyNpcState(state.npcs);
          } else if(packet.type==='dialogue')setDialogues(current=>current.some(item=>String(item.id)===String(packet.payload.id))?current:[...current,packet.payload as Dialogue].slice(-200));
          else if(packet.type==='coin_event'||packet.type==='inventory_changed'){
            const item=packet.payload as {npcId:string};
            if(item.npcId===selectedIdRef.current)void readApi<NpcActivity>(`/api/npcs/${encodeURIComponent(item.npcId)}/activity`).then(value=>{if(!stopped&&selectedIdRef.current===item.npcId)setNpcActivity(value);}).catch(()=>{});
          }
          else if(packet.type==='usage_changed')window.dispatchEvent(new Event('theote:usage-changed'));
          else if(packet.type==='agreement_changed')window.dispatchEvent(new Event('theote:agreements-changed'));
          else if(packet.type==='invitation_changed')window.dispatchEvent(new Event('theote:invitations-changed'));
          else if(packet.type==='agent_event'){
            const item=packet.payload as LiveEvent;setLiveEvents(current=>[...current,item].slice(-40));
            if(item.stage==='decision'&&item.status==='completed'&&item.tool){
              const eventKey=String(item.eventId??`${item.npcId}:${item.at}:${item.tool}`);
              if(seenActionEvents.current.has(eventKey))return;
              seenActionEvents.current.add(eventKey);
              if(seenActionEvents.current.size>500)seenActionEvents.current.delete(seenActionEvents.current.values().next().value!);
              const toast={id:crypto.randomUUID(),npcName:item.npcName,action:actionLabel(item.tool),description:item.thought||item.outcome||'',outcome:item.outcome||''};
              setActionToasts(current=>[...current,toast].slice(-4));
              const timer=window.setTimeout(()=>{setActionToasts(current=>current.filter(entry=>entry.id!==toast.id));toastTimers.current.delete(timer);},4000);
              toastTimers.current.add(timer);
            }
            if(item.npcId===selectedIdRef.current)void readApi<NpcActivity>(`/api/npcs/${encodeURIComponent(item.npcId)}/activity`).then(value=>{if(!stopped&&selectedIdRef.current===item.npcId)setNpcActivity(value);}).catch(()=>{});
          }
        } catch {/* Ignore malformed frames and keep the reconnect loop alive. */}
      };
      socket.onopen=()=>{if(!stopped){window.dispatchEvent(new Event('theote:usage-changed'));window.dispatchEvent(new Event('theote:agreements-changed'));window.dispatchEvent(new Event('theote:invitations-changed'));}};
      socket.onclose=()=>{if(!stopped)retry=window.setTimeout(connect,1200);};
    };
    connect();
    return()=>{stopped=true;if(retry)clearTimeout(retry);socket?.close();for(const timer of toastTimers.current)clearTimeout(timer);toastTimers.current.clear();instance?.dispose();world.current=null;audio.current.dispose();};
  },[]);
  useEffect(()=>{if(apiState)return;const timer=window.setInterval(()=>setTime(getWorldTime()),1000);return()=>clearInterval(timer);},[apiState]);
  useEffect(()=>{const sync=()=>setFullscreen(Boolean(document.fullscreenElement));document.addEventListener('fullscreenchange',sync);return()=>document.removeEventListener('fullscreenchange',sync);},[]);
  useEffect(()=>{const shortcut=(event:KeyboardEvent)=>{if((event.metaKey||event.ctrlKey)&&event.key==='1'){event.preventDefault();world.current?.centerOn();changeZoom(76);}};window.addEventListener('keydown',shortcut);return()=>window.removeEventListener('keydown',shortcut);},[]);
  useEffect(()=>{const controller=new AbortController();void readApi<Dialogue[]>('/api/dialogues',controller.signal).then(value=>{setDialogues(current=>{const merged=new Map<string,Dialogue>();[...value,...current].forEach(item=>merged.set(String(item.id),item));return [...merged.values()].sort((a,b)=>Number(a.id)-Number(b.id)).slice(-200);});}).catch(()=>{});return()=>controller.abort();},[]);
  useEffect(()=>{const controller=new AbortController();const load=()=>void readApi<Agreement[]>('/api/agreements',controller.signal).then(setAgreements).catch(()=>{});load();window.addEventListener('theote:agreements-changed',load);return()=>{controller.abort();window.removeEventListener('theote:agreements-changed',load);};},[]);
  useEffect(()=>{const controller=new AbortController();const load=()=>void readApi<Invitation[]>('/api/invitations',controller.signal).then(setInvitations).catch(()=>{});load();window.addEventListener('theote:invitations-changed',load);return()=>{controller.abort();window.removeEventListener('theote:invitations-changed',load);};},[]);
  useEffect(()=>{const controller=new AbortController();setNpcActivity(null);void readApi<NpcActivity>(`/api/npcs/${encodeURIComponent(selectedId)}/activity`,controller.signal).then(setNpcActivity).catch(()=>{});return()=>controller.abort();},[selectedId]);
  useEffect(()=>{if(panel==='world')return;const close=(event:KeyboardEvent)=>{if(event.key==='Escape')setPanel('world');};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close);},[panel]);
  useEffect(()=>{if(panel==='dialogues')chatEndRef.current?.scrollIntoView({behavior:'smooth',block:'end'});},[panel,chatResidentId,chatPartnerId,dialogues]);
  useEffect(()=>{const controller=new AbortController();const params=new URLSearchParams({period,npc:filterNpc,model:filterModel,purpose:filterPurpose});const load=async()=>{try{const value=await readApi<UsageReport>(`/api/usage?${params}`,controller.signal);if(!controller.signal.aborted)setUsage(value);}catch{/* Keep the previous report visible while reconnecting. */}};void load();window.addEventListener('theote:usage-changed',load);return()=>{controller.abort();window.removeEventListener('theote:usage-changed',load);};},[period,filterNpc,filterModel,filterPurpose]);
  const selectedState=apiState?.npcs.find(person=>person.id===selectedId);
  const nearbyPeople=selectedState?apiState?.npcs.filter(person=>person.id!==selectedId&&person.mode!=='sleeping'&&person.mode!=='departed'&&Math.hypot(person.x-selectedState.x,person.z-selectedState.z)<=2)??[]:[];
  const latestSelectedEvent=liveEvents.slice().reverse().find(event=>event.npcId===selectedId);
  const selectedLiveEvent=latestSelectedEvent?.status==='started'?latestSelectedEvent:undefined;
  const focusPerson=(person=selected)=>{const current=apiState?.npcs.find(npc=>npc.id===person.id);world.current?.centerOn(current?.x??person.position[0],current?.z??person.position[2]);changeZoom(112);};
  const changeZoom=(value:number)=>{const next=Math.max(72,Math.min(180,value));setZoom(next);world.current?.setZoom(next/100);};
  const toggleFullscreen=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen?.();
  const timeOfDay=time.hour<5?'Madrugada':time.hour<11?'Manhã tranquila':time.hour<17?'Tarde ensolarada':time.hour<20?'Fim de tarde':'Noite calma';
  const selectPanel=(next:Panel)=>{setPanel(next);setMenuOpen(false);setMoreOpen(false);};
  const days=usage?.daily??[],maxDailyCost=Math.max(0.000001,...days.map(day=>day.cost_usd));
  const modelCosts={respan:usage?.models.filter(item=>item.model==='respan/span-01-lite').reduce((sum,item)=>sum+Number(item.cost_usd),0)??0,jev:usage?.models.filter(item=>item.model==='typesafe/jev-router').reduce((sum,item)=>sum+Number(item.cost_usd),0)??0,jev113:usage?.models.filter(item=>item.model==='typesafe/jev-1.13').reduce((sum,item)=>sum+Number(item.cost_usd),0)??0,nano:usage?.models.filter(item=>item.model==='openai/gpt-4.1-nano').reduce((sum,item)=>sum+Number(item.cost_usd),0)??0,mistral:usage?.models.filter(item=>item.model==='mistralai/mistral-nemo').reduce((sum,item)=>sum+Number(item.cost_usd),0)??0,ling:usage?.models.filter(item=>item.model==='inclusionai/ling-3.1-flash').reduce((sum,item)=>sum+Number(item.cost_usd),0)??0,qwen:usage?.models.filter(item=>item.model==='qwen/qwen3.7-flash').reduce((sum,item)=>sum+Number(item.cost_usd),0)??0};
  const conversationThreads=(()=>{const groups=new Map<string,{key:string;title:string;ids:string[];messages:Dialogue[];latest:number}>();for(const message of dialogues){const ids=message.participants?.length?message.participants.slice().sort():[message.from_npc_id,message.to_npc_id].filter((id):id is string=>Boolean(id)).sort();if(ids.length<2)continue;const key=ids.join(':');const personName=(id:string)=>profiles.find(person=>person.id===id)?.name??id;const title=ids.length>2?`Grupo · ${ids.map(personName).join(', ')}`:ids.map(personName).join(' · ');const group=groups.get(key)??{key,ids,title,messages:[],latest:0};group.messages.push(message);group.latest=Math.max(group.latest,Number(message.id));groups.set(key,group);}return [...groups.values()].map(group=>({...group,messages:group.messages.sort((a,b)=>Number(a.id)-Number(b.id))})).sort((a,b)=>b.latest-a.latest);})();
  const residentThreads=conversationThreads.filter(thread=>chatResidentId&&thread.ids.includes(chatResidentId));
  const activeThread=residentThreads.find(thread=>thread.key===chatPartnerId)??residentThreads[0];
  const filteredEmotions=emotionCatalog.filter(emotion=>emotion.id!=='neutral'&&`${emotion.label} ${emotion.description}`.toLocaleLowerCase('pt-BR').includes(emotionSearch.toLocaleLowerCase('pt-BR')));
  const selectedEmotion=emotionDetail?emotionById.get(emotionDetail)??{id:emotionDetail,label:emotionLabel(emotionDetail),group:'Registro anterior',description:'Sentimento registrado antes do novo catálogo de emoções.'}:undefined;
  const emotionEvents=npcActivity?.feelings?.filter(feeling=>feeling.emotion===emotionDetail&&feeling.other_id===emotionTargetId)??[];
  const experiencedEmotionIds=new Set(npcActivity?.bondEmotions?.filter(feeling=>feeling.other_id===emotionTargetId).map(feeling=>feeling.emotion)??[]);
  const emotionTarget=npcActivity?.bonds?.find(bond=>bond.other_id===emotionTargetId);

  return <main className="app-shell">
    <div className="world-view" ref={mount} aria-label="Visão superior do mundo 3D de Theote"/><div className="vignette"/>
    <header className="topbar">
      <button className="brand brand-button" onClick={()=>selectPanel('world')} aria-label="Página inicial de Theote"><div className="brand-mark"><span/><span/><span/><span/></div><span>Theote</span><i/></button>
      <div className="world-title-wrap"><button className="world-title" onClick={()=>setMenuOpen(!menuOpen)} aria-expanded={menuOpen}><span className="eyebrow">THE ENDS OF THE EARTH</span><strong>Vale do começo <ChevronDown size={15}/></strong></button>{menuOpen&&<div className="popover world-popover"><b>Vale do começo</b><span>Um pequeno lar nos confins do mundo.</span><div className="popover-stats"><span><Home size={13}/> 4 casas</span><span><Bot size={13}/> {apiState?.npcs.filter(person=>person.mode!=='departed').length??profiles.length} moradores no vale</span></div><button onClick={()=>{world.current?.centerOn();changeZoom(76);setMenuOpen(false);}}>Centralizar visão</button></div>}</div>
      <div className="top-actions"><div className="live-pill"><span/>MUNDO ATIVO</div><button className="icon-button" aria-label={fullscreen?'Sair da tela cheia':'Expandir'} title={fullscreen?'Sair da tela cheia':'Tela cheia'} onClick={toggleFullscreen}><Expand size={17}/></button><div className="avatar" title="Seu mundo">T</div></div>
    </header>
    <section className="world-meta"><div className="weather"><div className="sun">{time.hour>=19||time.hour<6?'☾':'☼'}</div><div><b>{timeOfDay}</b><small>{formatWorldDate(time.day)}</small></div></div><div className="meta-divider"/><div className="clock"><span>HORA DO MUNDO</span><b>{formatWorldClock(time.hour,time.minute)}</b></div></section>
    <aside className="left-rail" aria-label="Navegação"><button className={`rail-btn ${panel==='world'?'selected':''}`} aria-label="Mundo" title="Mundo" aria-pressed={panel==='world'} onClick={()=>selectPanel('world')}><Compass size={18}/></button><button className="rail-btn" aria-label="Ver duende acorrentado" title="Ver duende acorrentado" onClick={()=>{selectPanel('world');world.current?.centerOn(CHAINED_GOBLIN.x,CHAINED_GOBLIN.z);changeZoom(180);}}><Eye size={18}/></button><button className={`rail-btn ${panel==='people'?'selected':''}`} aria-label="Habitantes" title="Habitantes" aria-pressed={panel==='people'} onClick={()=>selectPanel('people')}><Bot size={18}/></button><button className={`rail-btn ${panel==='activity'?'selected':''}`} aria-label="Atividade" title="Atividade" aria-pressed={panel==='activity'} onClick={()=>selectPanel('activity')}><Activity size={18}/></button><button className={`rail-btn ${panel==='dialogues'?'selected':''}`} aria-label="Conversas" title="Conversas" aria-pressed={panel==='dialogues'} onClick={()=>selectPanel('dialogues')}><MessageCircle size={18}/></button><button className={`rail-btn ${panel==='invitations'?'selected':''}`} aria-label="Convites" title="Convites para conversar" aria-pressed={panel==='invitations'} onClick={()=>selectPanel('invitations')}><CalendarDays size={18}/></button><button className={`rail-btn ${panel==='agreements'?'selected':''}`} aria-label="Acordos" title="Acordos" aria-pressed={panel==='agreements'} onClick={()=>selectPanel('agreements')}><ScrollText size={18}/></button><button className={`rail-btn ${panel==='usage'?'selected':''}`} aria-label="Consumo de IA" title="Consumo de IA" aria-pressed={panel==='usage'} onClick={()=>selectPanel('usage')}><BarChart3 size={18}/></button><button className={`rail-btn ${panel==='about'?'selected':''}`} aria-label="Sobre" title="Sobre" aria-pressed={panel==='about'} onClick={()=>selectPanel('about')}><Info size={18}/></button><div className="rail-line"/><button className="rail-btn" aria-label={muted?'Ativar som ambiente':'Silenciar som ambiente'} title={muted?'Ativar som ambiente':'Silenciar som ambiente'} aria-pressed={!muted} onClick={()=>{const nextMuted=!muted;setMuted(nextMuted);void audio.current.setEnabled(!nextMuted);}}>{muted?<VolumeX size={18}/>:<Volume2 size={18}/>}</button></aside>
    {panel!=='world'&&<div className="modal-backdrop"><section className={`npc-card modal-card ${panel==='usage'?'usage-card':''} ${panel==='people'?'people-card':''}`} role="dialog" aria-modal="true" aria-labelledby="modal-title">
      <div className="roster-heading"><div><span className="eyebrow">{panel==='people'?'PAINEL DO MORADOR':panel==='activity'?'DIÁRIO DO MUNDO':panel==='dialogues'?'CONVERSAS':panel==='invitations'?'CONVITES PARA CONVERSAR':panel==='agreements'?'ACORDOS POR ESCRITO':panel==='about'?'SOBRE O MUNDO':'USO DA INTELIGÊNCIA ARTIFICIAL'}</span><b id="modal-title">{panel==='people'?selected.name:panel==='activity'?'Últimos acontecimentos':panel==='dialogues'?'Conversas dos moradores':panel==='invitations'?'Encontros combinados':panel==='agreements'?'Compromissos do vale':panel==='about'?'Theote e Cardial':'Tokens e custos'}</b></div><button className="modal-close" aria-label="Fechar janela" title="Fechar" onClick={()=>selectPanel('world')}><X size={19}/></button></div>
      {panel==='people'&&<>
        <div className="roster resident-roster">{profiles.map(person=><button className={`resident ${selectedId===person.id?'active-resident':''}`} key={person.id} onClick={()=>{setSelectedId(person.id);setResidentView('overview');setEmotionDetail(null);setEmotionTargetId(null);focusPerson(person);}}><div className="resident-face" style={{backgroundColor:person.appearance.clothing}}><span style={{backgroundColor:person.appearance.skin}}/><i style={{backgroundColor:person.appearance.hair}}/></div><div className="resident-copy"><strong>{person.name}</strong><small>Casa {person.home.slice(-1)}</small></div></button>)}</div>
        <nav className="resident-tabs" aria-label={`Painel de ${selected.name}`}>{([['overview','Agora'],['inventory','Inventário'],['relationships','Relações'],['emotions','Emoções'],['journal','Diário'],['records','Registros']] as const).map(([view,label])=><button key={view} className={residentView===view?'active':''} aria-current={residentView===view?'page':undefined} onClick={()=>{setResidentView(view);setEmotionDetail(null);}}>{label}</button>)}</nav>
        <div className="resident-panel-body" role="region" aria-label={`${selected.name}: ${residentView}`} tabIndex={0}>
          {residentView==='overview'&&<div className="resident-page">
            <div className="resident-intro"><div><span>Casa {selected.home.slice(-1)} · {selectedState?.mode==='departed'?'no mundo exterior':selectedState?.mode==='sleeping'?'dormindo':selectedState?.mode==='walking'?'em movimento':selectedState?.mode==='following'?'acompanhando alguém':'acordado'}</span><h2>{selected.name} agora</h2><p>{selected.personality.slice(0,2).join(' · ')}</p></div><strong>{Math.round(selectedState?.stamina??100)}<small>% energia</small></strong></div>
            <div className="needs-strip" aria-label="Necessidades do morador"><div><span>Fome</span><b>{Number(selectedState?.hunger??npcActivity?.npc.hunger??0).toFixed(4)}%</b><i><em style={{width:`${Number(selectedState?.hunger??npcActivity?.npc.hunger??0).toFixed(4)}%`}}/></i></div><div><span>Sede</span><b>{Number(selectedState?.thirst??npcActivity?.npc.thirst??0).toFixed(4)}%</b><i><em style={{width:`${Number(selectedState?.thirst??npcActivity?.npc.thirst??0).toFixed(4)}%`}}/></i></div></div>
            <section className="resident-section coin-summary"><div className="section-heading"><h3>Moedas de {selected.name}</h3><strong>{selectedState?.coins??npcActivity?.npc.coins??0} ◈</strong></div><p>Na banca, comida e bebida custam moedas. Com 1000 moedas, {selected.name} pode sair sozinho para ver o mundo exterior.</p>{Boolean(npcActivity?.coins?.length)&&<div className="coin-history">{npcActivity?.coins.slice(0,5).map(entry=><div key={entry.id}><span>{entry.kind==='earned'?'Moeda recebida':entry.kind==='given'?`Deu a ${profiles.find(person=>person.id===entry.other_id)?.name??entry.other_id}`:entry.kind==='spent'?'Visita ao mundo exterior':`Recebeu de ${profiles.find(person=>person.id===entry.other_id)?.name??entry.other_id}`}</span><b>{entry.kind==='given'||entry.kind==='spent'?'-':'+'}{entry.amount}</b><small>{formatWorldDate(entry.world_day)} · saldo {entry.balance_after}</small></div>)}</div>}</section>
            <div className="resident-facts"><button onClick={()=>setResidentView('emotions')}><small>Sentimento atual</small><b>{emotionLabel(npcActivity?.affect?.mood??'neutral')}</b><span>{npcActivity?.affect?.pressure??0}/100 de emoções acumuladas</span></button><div><small>Expressão</small><b>{emotionLabel(selectedState?.emotion??'neutral')}</b><span>{selectedState?.next_thought_at?`Próxima decisão em ${formatWait(selectedState.next_thought_at)}`:'Disponível para agir'}</span></div></div>
            <section className="resident-section"><div className="section-heading"><h3>Quem está por perto</h3><small>Conversa a até 2 m</small></div><div className="nearby-list">{nearbyPeople.length?nearbyPeople.map(person=><div key={person.id}><b>{profiles.find(profile=>profile.id===person.id)?.name??person.id}</b><span>{Math.hypot(person.x-(selectedState?.x??0),person.z-(selectedState?.z??0)).toFixed(1)} m · Pode conversar, convidar e{(npcActivity?.affect?.pressure??0)>=55?' desabafar':' interagir'}</span></div>):<p>Ninguém está perto agora. {selected.name} sabe onde os outros estão e pode ir até eles.</p>}</div></section>
            <section className="resident-section"><div className="section-heading"><h3>Relações</h3><button onClick={()=>setResidentView('relationships')}>Ver todas</button></div><div className="relationship-preview">{npcActivity?.bonds?.map(bond=><button key={bond.other_id} onClick={()=>setResidentView('relationships')}><b>{bond.name}</b><span>{emotionLabel(npcActivity.feelings?.find(feeling=>feeling.other_id===bond.other_id)?.emotion??'neutral')}</span></button>)}</div></section>
            <section className="resident-section"><div className="section-heading"><h3>Últimas ações</h3><small>10 mais recentes · ferramenta e dados enviados</small></div><RecentActions decisions={npcActivity?.decisions} emptyMessage={`As escolhas aparecerão quando ${selected.name} agir.`}/></section>
          </div>}
          {residentView==='inventory'&&<div className="resident-page pantry-page"><div className="page-intro"><h2>Bolsa de {selected.name}</h2><p>Alimentos e bebidas podem ser consumidos ou doados a alguém a até 2 m.</p></div><div className="needs-strip" aria-label="Necessidades do morador"><div><span>Fome</span><b>{Number(selectedState?.hunger??npcActivity?.npc.hunger??0).toFixed(4)}%</b><i><em style={{width:`${Number(selectedState?.hunger??npcActivity?.npc.hunger??0).toFixed(4)}%`}}/></i></div><div><span>Sede</span><b>{Number(selectedState?.thirst??npcActivity?.npc.thirst??0).toFixed(4)}%</b><i><em style={{width:`${Number(selectedState?.thirst??npcActivity?.npc.thirst??0).toFixed(4)}%`}}/></i></div></div><section className="resident-section"><div className="section-heading"><h3>O que carrega</h3><small>{npcActivity?.inventory.reduce((sum,item)=>sum+item.quantity,0)??0} itens</small></div><div className="pantry-grid">{GOODS.map(good=>{const count=npcActivity?.inventory.find(item=>item.item_id===good.id)?.quantity??0;return <div className={count?'stocked':''} key={good.id}><span aria-hidden="true">{itemIcons[good.id]??'◈'}</span><strong>{good.name}</strong><b>×{count}</b></div>})}</div></section><section className="market-panel"><div><small>Banca do vale · {MARKET.x}, {MARKET.z}</small><h3>Comida para levar</h3><p>Os moradores compram quando estão próximos. O estoque da banca se renova.</p><button onClick={()=>{world.current?.centerOn(MARKET.x,MARKET.z);changeZoom(125);selectPanel('world');}}>Ver banca no mapa</button></div><div className="market-prices">{GOODS.map(good=><span key={good.id}>{good.name}<b>{good.price} ◈ · −{good.relief}% {good.kind==='food'?'fome':'sede'}{good.joy?` · +${good.joy} alegria`:''}</b></span>)}</div></section><section className="resident-section"><div className="section-heading"><h3>Movimentos da bolsa</h3></div><div className="journal-list">{npcActivity?.itemEvents.length?npcActivity.itemEvents.map(event=><article key={event.id}><small>{formatWorldDate(event.world_day)}</small><p>{event.kind==='bought'?'Comprou':event.kind==='consumed'?'Consumiu':event.kind==='given'?'Doou':'Recebeu'} {GOODS.find(good=>good.id===event.item_id)?.name??event.item_id}{event.other_id?` · ${profiles.find(person=>person.id===event.other_id)?.name??event.other_id}`:''}{event.kind==='consumed'&&event.need_before!=null&&event.need_after!=null?` · ${Number(event.need_before).toFixed(2)}% → ${Number(event.need_after).toFixed(2)}% ${GOODS.find(good=>good.id===event.item_id)?.kind==='food'?'fome':'sede'}`:''}{event.joy_gain?` · +${event.joy_gain} alegria`:''}</p></article>):<p className="resident-empty">A bolsa ainda não foi usada.</p>}</div></section></div>}
          {residentView==='relationships'&&<div className="resident-page"><div className="page-intro"><h2>O que {selected.name} sente pelos outros</h2><p>Os sentimentos são individuais e mudam conforme as conversas e acontecimentos.</p></div><div className="relationship-grid">{npcActivity?.bonds?.map(bond=>{const emotions=npcActivity.bondEmotions?.filter(item=>item.other_id===bond.other_id)??[];const latest=npcActivity.feelings?.find(item=>item.other_id===bond.other_id);return <article className="relationship-card" key={bond.other_id}><div className="relationship-title"><b>{bond.name}</b><span>{bond.warmth>25?'Próximos':bond.warmth< -20?'Distantes':'Se conhecendo'}</span></div><div className="relationship-metrics"><span>Carinho <b>{bond.warmth}</b></span><span>Confiança <b>{bond.trust}</b></span><span>Tensão <b>{bond.tension}</b></span></div><div className="emotion-chips">{emotions.length?emotions.map(item=><button key={item.emotion} onClick={()=>{setEmotionTargetId(bond.other_id);setEmotionDetail(item.emotion);setResidentView('emotions');}}>{emotionLabel(item.emotion)} · {item.strength}</button>):<small>Ainda não há sentimentos registrados.</small>}</div>{latest&&<p className="relationship-latest">Último sentimento: {emotionLabel(latest.emotion)} — {latest.cause}</p>}</article>})}</div></div>}
          {residentView==='emotions'&&<div className="resident-page emotions-page">{!emotionTargetId?<><div className="page-intro"><h2>Sentimentos de {selected.name}</h2><p>Escolha uma pessoa para ver o que {selected.name} sente por ela. Cada lado da relação é independente.</p></div><div className="emotion-person-picker">{npcActivity?.bonds?.map(bond=>{const count=npcActivity.bondEmotions?.filter(item=>item.other_id===bond.other_id).length??0;return <button key={bond.other_id} onClick={()=>{setEmotionTargetId(bond.other_id);setEmotionDetail(null);}}><b>{selected.name} → {bond.name}</b><span>{count?`${count} sentimentos registrados`:'Ainda sem sentimentos registrados'}</span></button>})}</div></>:selectedEmotion?<><button className="resident-back" onClick={()=>setEmotionDetail(null)}>← Emoções por {emotionTarget?.name}</button><div className="emotion-detail"><small>{selected.name} → {emotionTarget?.name} · {selectedEmotion.group}</small><h2>{selectedEmotion.label}</h2><p>{selectedEmotion.description}</p><strong>{emotionEvents.length} {emotionEvents.length===1?'vez':'vezes'} registrada{emotionEvents.length===1?'':'s'}</strong></div><div className="emotion-event-list">{emotionEvents.length?emotionEvents.map(feeling=><article key={feeling.id}><b>{formatWorldDate(feeling.world_day)}</b><p>{feeling.cause}</p><small>Intensidade {feeling.intensity}/4</small></article>):<p>{selected.name} ainda não sentiu {selectedEmotion.label.toLocaleLowerCase('pt-BR')} por {emotionTarget?.name}.</p>}</div></>:<><button className="resident-back" onClick={()=>setEmotionTargetId(null)}>← Escolher outra pessoa</button><div className="page-intro"><h2>{selected.name} sente por {emotionTarget?.name}</h2><p>{emotionCatalog.length-1} sentimentos possíveis. Toque em um para ver os registros desta relação.</p></div><button className="reverse-relationship" onClick={()=>{const other=profiles.find(person=>person.id===emotionTargetId);if(other){setEmotionTargetId(selectedId);setSelectedId(other.id);setEmotionDetail(null);focusPerson(other);}}}>Ver o que {emotionTarget?.name} sente por {selected.name} ↗</button><label className="emotion-search">Buscar emoção<input value={emotionSearch} onChange={event=>setEmotionSearch(event.target.value)} placeholder="Ex.: paixão, carinho, saudade"/></label><div className="emotion-catalog">{(['Afeto','Bem-estar','Reflexão','Vulnerabilidade','Conflito'] as const).map(group=>{const entries=filteredEmotions.filter(emotion=>emotion.group===group);return entries.length?<section key={group}><h3>{group}</h3><div>{entries.map(emotion=><button key={emotion.id} onClick={()=>setEmotionDetail(emotion.id)} className={experiencedEmotionIds.has(emotion.id)?'felt':''}><b>{emotion.label}</b><span>{emotion.description}</span>{experiencedEmotionIds.has(emotion.id)&&<i>Sentiu</i>}</button>)}</div></section>:null})}</div></>}</div>}
          {residentView==='records'&&<div className="resident-page records-page"><div className="page-intro"><h2>Registros de {selected.name}</h2><p>Convites, acordos, descobertas e lembranças que orientam suas próximas decisões.</p></div><section className="resident-section"><h3>Identidade e rotina</h3><article className="record-entry"><b>{selected.name} · {selected.gender} · casa {selected.home.slice(-1)}</b><p>Jeito: {selected.personality.join(", ")}. Interesses: {selected.interests.join(", ")}. Horário habitual de dormir: {String(selected.sleepHour).padStart(2,"0")}:00.</p><p>Laços de origem: {Object.entries(selected.relationships).map(([id,relation])=>`${profiles.find(person=>person.id===id)?.name??id}: ${relation}`).join("; ")||"não registrados"}.</p></article></section><section className="resident-section"><h3>Convites para conversar</h3><InvitationList items={npcActivity?.invitations??[]} /></section><section className="resident-section"><h3>Acordos por escrito</h3>{npcActivity?.agreements.length?npcActivity.agreements.map(item=><article className="record-entry" key={item.id}><b>{item.status==='signed'?'Firmado':item.status==='declined'?'Recusado':'Pendente'}</b><p>{item.terms}</p></article>):<p className="resident-empty">Nenhum acordo registrado.</p>}</section><section className="resident-section"><h3>Opiniões atuais</h3>{npcActivity?.beliefs.map(item=><article className="record-entry" key={item.topic}><b>{item.topic} · {item.stance}/100</b><p>{item.reason||'Ainda sem motivo registrado.'}</p></article>)}</section><section className="resident-section"><h3>Descobertas</h3>{npcActivity?.explorations.length?npcActivity.explorations.map(item=><article className="record-entry" key={item.site_id}><b>{item.site_id} · {formatWorldDate(item.world_day)}</b><p>{item.discovery}</p></article>):<p className="resident-empty">Ainda não explorou um lugar novo.</p>}</section><section className="resident-section"><h3>Lembranças episódicas</h3>{npcActivity?.memoryEvents.length?npcActivity.memoryEvents.map(item=><article className="record-entry" key={item.id}><b>{formatWorldDate(item.world_day)} · importância {item.importance}</b><p>{item.summary}</p></article>):<p className="resident-empty">As experiências ainda estão começando.</p>}</section><section className="resident-section"><h3>Notificações</h3>{npcActivity?.notifications.length?npcActivity.notifications.map(item=><article className="record-entry" key={item.id}><p>{item.message}</p></article>):<p className="resident-empty">Nenhuma notificação recente.</p>}</section></div>}
          {residentView==='journal'&&<div className="resident-page"><div className="page-intro"><h2>Diário de {selected.name}</h2><p>Escolhas e conversas guardadas para os próximos dias.</p></div>{selectedLiveEvent&&<p className="live-thought">{selectedLiveEvent.npcName} está {selectedLiveEvent.stage==='tool'?`executando ${actionLabel(selectedLiveEvent.tool??'ação')}`:selectedLiveEvent.stage==='movement'?'caminhando':'decidindo'} há {Math.max(0,((Date.now()-new Date(selectedLiveEvent.at).getTime())/1000)).toFixed(1)} s.</p>}<section className="resident-section"><div className="section-heading"><h3>Memória</h3></div><p className="memory-copy">{npcActivity?.memory?.summary||'Ainda não há lembranças resumidas.'}</p></section><section className="resident-section"><div className="section-heading"><h3>Últimas ações</h3><small>10 mais recentes · ferramenta e dados enviados</small></div><RecentActions decisions={npcActivity?.decisions} emptyMessage="Ainda não há decisões."/></section><section className="resident-section"><div className="section-heading"><h3>Conversas recentes</h3></div><div className="journal-list">{npcActivity?.dialogue.slice().reverse().map(item=><article key={item.id}><small>{stamp(item)} · {item.speaker_name}</small><p>{item.content}</p></article>)}</div></section></div>}
        </div>
      </>}
      {panel==='activity'&&<div className="activity-feed"><article><span className="feed-dot"/><div><b>O dia {time.day} começou</b><p>A luz e o céu acompanham o relógio do mundo.</p><small>Agora · {formatWorldClock(time.hour,time.minute)}</small></div></article>{liveEvents.slice(-15).reverse().map((item,index)=><article key={`${item.at}-${index}`}><span className="feed-dot"/><div><b>{item.npcName} · {item.status==='started'?(item.stage==='movement'?'caminhando':item.stage==='tool'?'executando uma ação':'decidindo'):item.status==='completed'?'concluiu':'erro'}</b><p>{item.tool?.replaceAll('_',' ')||item.outcome||item.stage}</p>{item.status==='started'&&<small>Em andamento · {Math.max(0,((Date.now()-new Date(item.at).getTime())/1000)).toFixed(1)} s</small>}</div></article>)}{dialogues.slice(-3).reverse().map(item=><article key={item.id}><span className="feed-dot"/><div><b>{item.speaker_name} falou</b><p>{item.content}</p><small>{stamp(item)}</small></div></article>)}</div>}
      {panel==='about'&&<AboutPanel/>}
      {panel==='dialogues'&&<><div className="resident-chat-layout"><nav className="chat-residents" aria-label="Moradores">{profiles.map(person=><button key={person.id} className={chatResidentId===person.id?'active-resident':''} onClick={()=>{setChatResidentId(person.id);setChatPartnerId(null);}}>{person.name}</button>)}</nav><div className="chat-content">{!chatResidentId?<div className="empty-state"><MessageCircle size={20}/><p>Escolha um morador para ver as conversas.</p></div>:!activeThread?<div className="empty-state"><MessageCircle size={20}/><p>{profiles.find(person=>person.id===chatResidentId)?.name} ainda não tem conversas registradas.</p></div>:<><nav className="chat-partners" aria-label="Conversas">{residentThreads.map(thread=><button key={thread.key} className={(chatPartnerId??residentThreads[0]?.key)===thread.key?'active-resident':''} onClick={()=>setChatPartnerId(thread.key)}>{thread.title}<small>{thread.messages.length} mensagens</small></button>)}</nav><header className="active-chat-heading"><b>{activeThread.title}</b><span>{activeThread.ids.length>2?'Conversa em grupo · todos podem participar':'Conversa entre moradores próximos'}</span></header><div className="thread-messages chat-transcript">{activeThread.messages.map(item=><article key={item.id} id={`chat-message-${item.id}`}><b>{item.speaker_name}</b>{item.reply_to_message_id&&<div className="chat-reply" aria-label={`Resposta à mensagem de ${item.reply_to_speaker_name??"outro morador"}`}><strong>{item.reply_to_speaker_name??"Mensagem anterior"}</strong><span>{item.reply_to_content??"Mensagem indisponível"}</span></div>}<p>{item.content}</p><small>{stamp(item)}</small></article>)}<div ref={chatEndRef}/></div></>}</div></div><div className="proximity-note">Quem está na mesma roda ouve a conversa. Ao se afastar, deixa de receber novas falas.</div></>}
      {panel==='invitations'&&<div className="invitations-page"><p>O convite nasce de uma conversa. Cada pessoa decide se aceita e, perto da hora, se vai comparecer.</p><InvitationList items={invitations}/></div>}
      {panel==='agreements'&&<div className="agreements-page"><p className="agreements-intro">Cada proposta nasce de uma fala registrada. O compromisso só entra em vigor quando a outra pessoa aceita.</p><div className="agreements-summary"><span><b>{agreements.filter(item=>item.status==='signed').length}</b> firmados</span><span><b>{agreements.filter(item=>item.status==='proposed').length}</b> aguardando resposta</span></div><div className="agreements-list">{agreements.length?agreements.map(item=><article className={`agreement-paper ${item.status}`} key={item.id}><header><span>Acordo #{item.id}</span><strong>{item.status==='signed'?'Firmado':item.status==='declined'?'Recusado':'Proposta'}</strong></header><p>{item.terms}</p><footer><span>{item.proposer_name} propôs a {item.recipient_name}</span><small>{formatWorldDate(item.proposed_day)}{item.decided_day?` · decisão em ${formatWorldDate(item.decided_day)}`:''}</small></footer></article>):<div className="empty-state"><ScrollText size={24}/><p>Os moradores ainda não registraram propostas. Quando um plano dito em conversa virar acordo, ele aparecerá aqui.</p></div>}</div></div>}
      {panel==='usage'&&<>{usage?<><div className="usage-filters"><label>Período<select value={period} onChange={event=>setPeriod(event.target.value)}><option value="day">Hoje</option><option value="month">Este mês</option><option value="all">Desde o início</option></select></label><label>Morador<select value={filterNpc} onChange={event=>setFilterNpc(event.target.value)}><option value="all">Todos</option>{profiles.map(person=><option value={person.id} key={person.id}>{person.name}</option>)}</select></label><label>Modelo<select value={filterModel} onChange={event=>setFilterModel(event.target.value)}><option value="all">Todos</option><option value="respan/span-01-lite">Respan · decisões</option><option value="typesafe/jev-router">Jev Router · histórico</option><option value="typesafe/jev-1.13">Jev 1.13 · histórico</option><option value="openai/gpt-4.1-nano">GPT-4.1 Nano · reserva de decisões</option><option value="inclusionai/ling-3.1-flash">Ling · conversas</option><option value="mistralai/mistral-nemo">Mistral Nemo · reserva</option><option value="qwen/qwen3.7-flash">Qwen · histórico</option></select></label><label>Tipo<select value={filterPurpose} onChange={event=>setFilterPurpose(event.target.value)}><option value="all">Todos</option><option value="decision">Decisões</option><option value="dialogue">Diálogos</option><option value="summary">Resumos</option></select></label></div><div className="usage-stats"><div><span>TOKENS</span><b>{usage.filters.total_tokens.toLocaleString('pt-BR')}</b><small>{usage.filters.prompt_tokens.toLocaleString('pt-BR')} entrada · {usage.filters.completion_tokens.toLocaleString('pt-BR')} saída</small></div><div><span>CUSTO DO PERÍODO</span><b>{money(usage.filters.cost_usd)}</b><small>{usage.filters.requests} chamadas</small></div><div><span>LIMITE MENSAL</span><b>{money(usage.budget.spentUsd)} / {money(usage.budget.budgetUsd)}</b><small>{money(usage.budget.remainingUsd)} restantes</small></div></div><p className="usage-reset-note">Relatório desde {new Date(usage.reportStartedAt).toLocaleString('pt-BR')}. O limite mensal ainda considera todos os gastos anteriores.</p><div className="usage-section"><b>Gasto diário por modelo</b><div className="usage-model-totals"><span className="respan"><i/>Respan <strong>{money(modelCosts.respan)}</strong></span>{modelCosts.jev>0&&<span className="jev"><i/>Jev Router (histórico) <strong>{money(modelCosts.jev)}</strong></span>}{modelCosts.jev113>0&&<span className="jev113"><i/>Jev 1.13 (histórico) <strong>{money(modelCosts.jev113)}</strong></span>}<span className="nano"><i/>GPT-4.1 Nano <strong>{money(modelCosts.nano)}</strong></span><span className="ling"><i/>Ling <strong>{money(modelCosts.ling)}</strong></span>{modelCosts.mistral>0&&<span className="mistral"><i/>Mistral Nemo <strong>{money(modelCosts.mistral)}</strong></span>}{modelCosts.qwen>0&&<span className="qwen"><i/>Qwen (histórico) <strong>{money(modelCosts.qwen)}</strong></span>}</div><div className="usage-days">{days.length?days.slice(-14).map(day=><div className="usage-day" key={day.date} title={`${day.date} · Respan ${money(day.respan_cost_usd)} · Jev Router ${money(day.jev_cost_usd)} · Jev 1.13 ${money(day.jev_113_cost_usd)} · GPT-4.1 Nano ${money(day.nano_cost_usd)} · Ling ${money(day.ling_cost_usd)} · Mistral ${money(day.mistral_cost_usd)} · Qwen ${money(day.qwen_cost_usd)}${day.other_cost_usd?` · Outros ${money(day.other_cost_usd)}`:""}`}><div className="usage-cost-track"><div className="usage-cost-stack" style={{height:`${day.cost_usd>0?Math.max(4,day.cost_usd/maxDailyCost*100):0}%`}}><i className="respan" style={{flex:Number(day.respan_cost_usd)}}/>{day.jev_cost_usd>0&&<i className="jev" style={{flex:Number(day.jev_cost_usd)}}/>}{day.jev_113_cost_usd>0&&<i className="jev113" style={{flex:Number(day.jev_113_cost_usd)}}/>}{day.nano_cost_usd>0&&<i className="nano" style={{flex:Number(day.nano_cost_usd)}}/>}<i className="ling" style={{flex:Number(day.ling_cost_usd)}}/>{day.mistral_cost_usd>0&&<i className="mistral" style={{flex:Number(day.mistral_cost_usd)}}/>}{day.qwen_cost_usd>0&&<i className="qwen" style={{flex:Number(day.qwen_cost_usd)}}/>}{day.other_cost_usd>0&&<i className="other" style={{flex:Number(day.other_cost_usd)}}/>}</div></div><small>{day.date.slice(5)}</small></div>):<span className="empty-usage">Ainda não há consumo registrado.</span>}</div><small className="usage-chart-note">Altura = custo total do dia. Passe o cursor para ver cada valor.</small></div><div className="usage-columns"><div className="usage-section"><b>Por morador</b>{usage.characters.map(person=><div className="usage-row" key={person.npc_id??person.character}><span>{person.character}</span><small>{person.tokens.toLocaleString('pt-BR')} tokens</small><b>{money(person.cost_usd)}</b></div>)}</div><div className="usage-section"><b>Por modelo e finalidade</b>{usage.models.map((item,index)=><div className="usage-row usage-model" key={`${item.model}-${item.purpose}-${index}`}><span>{item.model}<small>{purposeName(item.purpose)} · {item.requests} chamadas</small></span><b>{item.tokens.toLocaleString('pt-BR')} · {money(item.cost_usd)}</b></div>)}</div></div></>:<div className="empty-state"><BarChart3 size={21}/><p>Aguardando o servidor e o banco para carregar o uso.</p></div>}</>}
    </section></div>}
    {panel==='world'&&<section className="world-chat" aria-label="Conversas recentes"><div className="world-chat-log" aria-live="polite">{dialogues.slice(-6).map(item=><div key={item.id}><b>{item.speaker_name}</b>{item.reply_to_message_id&&<small>↳ {item.reply_to_speaker_name}: {item.reply_to_content}</small>}<span>{item.content}</span></div>)}</div><button onClick={()=>selectPanel('dialogues')}><MessageCircle size={15}/> Abrir chat</button></section>}
    <div className="action-toast-stack" aria-live="polite" aria-label="Ações recentes dos moradores">{actionToasts.map(toast=><article className="action-toast" key={toast.id}><span>{toast.npcName} · {toast.action}</span><p>{toast.description}</p>{toast.outcome&&toast.outcome!==toast.description&&<small>{toast.outcome}</small>}</article>)}</div>
    <div className="zoom-controls"><button aria-label="Diminuir zoom" title="Diminuir zoom" onClick={()=>changeZoom(zoom-10)}><Minus size={15}/></button><span>{zoom}%</span><button aria-label="Aumentar zoom" title="Aumentar zoom" onClick={()=>changeZoom(zoom+10)}><Plus size={15}/></button></div>
    <div className="bottom-note"><span className="keycap">W</span><span className="keycap">A</span><span className="keycap">S</span><span className="keycap">D</span><span className="hint">mover câmera</span><span className="mouse-icon">⌖</span><span className="hint">clique e arraste para mover · scroll para zoom</span></div>
  </main>;
}
